\mathsf{UStep}_{\mathsf{dm,elim}}
=
\left\{
\left(
(\{\operatorname{tvar}(a)\equiv_{\mathsf c}A\}\cup C,\theta),
(C[a:=A],\{a\mapsto A\}\circ\theta)
\right):
\begin{array}{l}
a\in\mathsf{TVar}_{\mathsf{dm}},\
A\in\mathsf{Mono}_{\mathsf{dm}},\
a\notin\operatorname{FTV}_{\mathsf{dm}}(A),\\
A\ne\operatorname{tvar}(a),\
C\in\mathsf{CSet}_{\mathsf{dm}},\
\theta\in\mathsf{TSub}_{\mathsf{dm}}
\end{array}
\right\},

\mathsf{UStep}_{\mathsf{dm,dec}}
=
\left\{
\left(
(\{\operatorname{arr}(A_1,A_2)\equiv_{\mathsf c}\operatorname{arr}(B_1,B_2)\}\cup C,\theta),
(\{A_1\equiv_{\mathsf c}B_1,A_2\equiv_{\mathsf c}B_2\}\cup C,\theta)
\right):
\begin{array}{l}
A_1,A_2,B_1,B_2\in\mathsf{Mono}_{\mathsf{dm}},\\
C\in\mathsf{CSet}_{\mathsf{dm}},\
\theta\in\mathsf{TSub}_{\mathsf{dm}}
\end{array}
\right\}.
